"""Yield to maturity, current yield, yield to worst -- and the money-market quotes that are
not yields at all.

WHY this exists: "5.00%" on a Treasury bill screen is a DISCOUNT RATE. It is not a yield, it
is not comparable to a note's yield to maturity, and converting it wrongly is worth tens of
basis points. Three separate arithmetic conventions collide here and none of them raises:

  * DISCOUNT BASIS. A bill discount rate is (100 - P)/100 * 360/days -- the gain divided by
    the FACE amount, on a 360-day year. A yield divides by the PRICE, on a 365-day year. The
    two disagree by more the longer and the higher the bill.

  * TREASURY'S OWN CONVERSION IS TWO FORMULAS. 31 CFR 356 Appendix B section VI gives a
    simple formula for bills of not more than one half-year and a QUADRATIC for longer ones,
    because a 52-week bill must be made comparable to a security that pays a coupon halfway
    through. Applying the short formula to a 364-day bill overstates the investment rate.

  * CURRENT YIELD AND YIELD TO WORST. Current yield ignores the pull to par entirely. Yield
    to maturity on a callable bond trading above par is not the yield you will earn.

The reference implementation reproduces both worked examples printed in 31 CFR 356 Appendix B
(8.076% and 8.237%), so the formulas are checked against the regulation and not against
themselves. QuantLib, when importable, checks the price/yield side.

Usage:
    from yield_measures import bill_price_from_discount, treasury_investment_rate, ytm
"""
from __future__ import annotations

import math
from typing import Sequence

from scipy.optimize import brentq

# 31 CFR 356 Appendix B, VI.B.2 applies "for bills of more than one half-year to maturity".
DAYS_IN_YEAR = 365.0
DISCOUNT_BASIS_DAYS = 360.0


# ------------------------------------------------------------------ bills
def bill_price_from_discount(discount: float, days: int, basis: float = DISCOUNT_BASIS_DAYS,
                             face: float = 100.0) -> float:
    """P = face * (1 - d * days / 360). The discount is quoted ON THE FACE, not on the price."""
    if days <= 0:
        raise ValueError("days must be positive")
    return face * (1.0 - discount * days / basis)


def bill_discount_from_price(price: float, days: int, basis: float = DISCOUNT_BASIS_DAYS,
                             face: float = 100.0) -> float:
    if price <= 0:
        raise ValueError("price must be positive")
    return (face - price) / face * basis / days


def money_market_yield(price: float, days: int, face: float = 100.0) -> float:
    """The add-on (CD-equivalent) rate: gain over PRICE, still on a 360-day year."""
    return (face - price) / price * DISCOUNT_BASIS_DAYS / days


def bond_equivalent_yield(price: float, days: int, year: float = DAYS_IN_YEAR,
                          face: float = 100.0) -> float:
    """Simple interest on the PRICE over a 365-day year -- the short-bill investment rate."""
    if price <= 0:
        raise ValueError("price must be positive")
    return (face - price) / price * year / days


def treasury_investment_rate(price: float, r: int, y: float = DAYS_IN_YEAR) -> float:
    """The investment rate (coupon-equivalent yield), 31 CFR 356 Appendix B section VI.

    Not more than one half-year (r <= y/2):   i = (100 - P)/P * y/r
    More than one half-year:                  P [1 + (r - y/2)(i/y)] (1 + i/2) = 100,
    solved as a quadratic with b = r/y, a = (r/2y) - .25, c = (P - 100)/P and
    i = (-b + sqrt(b^2 - 4ac)) / (2a).
    """
    if price <= 0:
        raise ValueError("price must be positive")
    if r <= 0:
        raise ValueError("r must be positive")
    if r <= y / 2.0:
        return (100.0 - price) / price * y / r
    b = r / y
    a = r / (2.0 * y) - 0.25
    c = (price - 100.0) / price
    disc = b * b - 4.0 * a * c
    if disc < 0.0:
        raise ValueError("no real investment rate for this price and maturity")
    return (-b + math.sqrt(disc)) / (2.0 * a)


def bill_table(discount: float, day_counts: Sequence[int], face: float = 1_000_000.0) -> list[dict]:
    """One discount rate across several maturities: the four numbers people confuse."""
    rows = []
    for d in day_counts:
        p = bill_price_from_discount(discount, d)
        bey = bond_equivalent_yield(p, d)
        inv = treasury_investment_rate(p, d)
        rows.append({"days": d, "price": p, "discount": discount,
                     "money_market_yield": money_market_yield(p, d),
                     "bond_equivalent_yield": bey, "investment_rate": inv,
                     "bp_discount_to_bey": 1e4 * (bey - discount),
                     "bp_bey_to_investment": 1e4 * (inv - bey),
                     "uses_quadratic": d > DAYS_IN_YEAR / 2.0,
                     "cash_gain": face * (100.0 - p) / 100.0})
    return rows


# ------------------------------------------------------------------ coupon bonds
def bond_price_from_yield(coupon: float, y: float, n: int, w: float = 1.0, freq: int = 2,
                          face: float = 100.0) -> dict:
    """Street-convention price of a coupon bond.

    n = number of remaining coupons, w = fraction of the current coupon period still to run
    (w = 1 on a coupon date). Cash flows land at w, w+1, ..., w+n-1 periods.
    Returns dirty, clean and accrued per `face`.
    """
    if n < 1:
        raise ValueError("n must be at least 1")
    if not 0.0 < w <= 1.0:
        raise ValueError("w must be in (0, 1]")
    c = face * coupon / freq
    v = 1.0 / (1.0 + y / freq)
    dirty = sum(c * v ** (w + k) for k in range(n)) + face * v ** (w + n - 1)
    accrued = c * (1.0 - w)
    return {"dirty": dirty, "accrued": accrued, "clean": dirty - accrued}


def ytm(clean: float, coupon: float, n: int, w: float = 1.0, freq: int = 2,
        face: float = 100.0) -> float:
    """Yield to maturity from a CLEAN price, by the same street convention."""
    def f(y):
        return bond_price_from_yield(coupon, y, n, w, freq, face)["clean"] - clean
    return brentq(f, -0.9, 5.0, xtol=1e-14, rtol=1e-15, maxiter=200)


def current_yield(coupon: float, clean: float, face: float = 100.0) -> float:
    """Annual coupon over the clean price. Ignores the pull to par completely."""
    if clean <= 0:
        raise ValueError("clean price must be positive")
    return face * coupon / clean


def yield_to_worst(clean: float, coupon: float, calls: Sequence[tuple[int, float]],
                   n_maturity: int, freq: int = 2, face: float = 100.0) -> dict:
    """`calls` is [(periods to the call, call price), ...]; maturity is added at `face`.

    Each candidate is repriced as a bullet redeeming at its own call price on its own date.
    The worst of them is the yield to worst.
    """
    cands = list(calls) + [(n_maturity, face)]
    out = []
    for n, redemption in cands:
        def f(y, n=n, redemption=redemption):
            c = face * coupon / freq
            v = 1.0 / (1.0 + y / freq)
            return sum(c * v ** (k + 1) for k in range(n)) + redemption * v ** n - clean
        out.append({"periods": n, "redemption": redemption,
                    "yield": brentq(f, -0.9, 5.0, xtol=1e-14, rtol=1e-15, maxiter=200)})
    worst = min(out, key=lambda r: r["yield"])
    to_maturity = out[-1]
    return {"candidates": out, "yield_to_worst": worst["yield"], "worst_at": worst["periods"],
            "yield_to_maturity": to_maturity["yield"],
            "bp_ytm_over_ytw": 1e4 * (to_maturity["yield"] - worst["yield"])}


# ------------------------------------------------------------------ QuantLib
def quantlib_cross_checks(discount: float, days: Sequence[int], coupon: float, y: float,
                          years: int) -> dict | None:
    """Check the bill arithmetic and the coupon-bond price/yield against QuantLib 1.43."""
    try:
        import QuantLib as ql
    except ImportError:
        return None
    out: dict = {"version": ql.__version__, "bills": []}
    for d in days:
        p = bill_price_from_discount(discount, d)
        bey = bond_equivalent_yield(p, d)
        rate = ql.InterestRate(bey, ql.Actual365Fixed(), ql.Simple, ql.Annual)
        out["bills"].append({"days": d, "price": p, "bey": bey,
                             "ql_compound_factor": rate.compoundFactor(d / 365.0),
                             "direct": 100.0 / p})
    settle = ql.Date(15, 1, 2026)
    ql.Settings.instance().evaluationDate = settle
    sched = ql.Schedule(settle, ql.Date(15, 1, 2026 + years), ql.Period(ql.Semiannual),
                        ql.UnitedStates(ql.UnitedStates.GovernmentBond), ql.Unadjusted,
                        ql.Unadjusted, ql.DateGeneration.Backward, False)
    dc = ql.ActualActual(ql.ActualActual.ISMA, sched)
    # Unadjusted payment dates: the default Following bumps coupons off weekends and adds a
    # few tenths of a basis point of discounting that has nothing to do with the yield formula.
    bond = ql.FixedRateBond(0, 100.0, sched, [coupon], dc, ql.Unadjusted)
    bond_following = ql.FixedRateBond(0, 100.0, sched, [coupon], dc, ql.Following)
    rate = ql.InterestRate(y, dc, ql.Compounded, ql.Semiannual)
    out["bond_clean"] = ql.BondFunctions.cleanPrice(bond, rate, settle)
    out["bond_clean_following"] = ql.BondFunctions.cleanPrice(bond_following, rate, settle)
    out["bond_yield"] = ql.BondFunctions.bondYield(
        bond, ql.BondPrice(out["bond_clean"], ql.BondPrice.Clean), dc, ql.Compounded,
        ql.Semiannual, settle)
    out["periods"] = 2 * years
    return out


