if __name__ == "__main__":
    W = 92
    DISCOUNT = 0.05
    DAYS = (28, 91, 182, 364)
    FACE = 1_000_000.0

    print("=" * W)
    print("YIELD MEASURES AND BILL QUOTES -- a 5.00% Treasury bill DISCOUNT RATE is not a yield")
    print("=" * W)

    print("\n1. THE SAME 5.00% BILL, FOUR WAYS")
    print(f"   {'days':>5}{'price':>12}{'discount':>11}{'MM yield':>11}{'BEY':>11}"
          f"{'inv. rate':>11}{'d->BEY':>10}{'BEY->IR':>10}")
    for r in bill_table(DISCOUNT, DAYS, FACE):
        print(f"   {r['days']:>5}{r['price']:>12.6f}{r['discount']:>11.4%}"
              f"{r['money_market_yield']:>11.4%}{r['bond_equivalent_yield']:>11.4%}"
              f"{r['investment_rate']:>11.4%}{r['bp_discount_to_bey']:>+10.1f}"
              f"{r['bp_bey_to_investment']:>+10.1f}")
    rows = {r["days"]: r for r in bill_table(DISCOUNT, DAYS, FACE)}
    print(f"   -> a 5.00% discount rate is a {rows[182]['bond_equivalent_yield']:.4%} yield at "
          f"182 days ({rows[182]['bp_discount_to_bey']:+.1f} bp), "
          f"{rows[91]['bond_equivalent_yield']:.4%} at 91 ({rows[91]['bp_discount_to_bey']:+.1f}"
          f" bp), {rows[364]['bond_equivalent_yield']:.4%} at 364 "
          f"({rows[364]['bp_discount_to_bey']:+.1f} bp)")
    print(f"   -> and above one half-year Treasury's own investment rate takes the quadratic: "
          f"{rows[364]['investment_rate']:.4%}, a further "
          f"{rows[364]['bp_bey_to_investment']:.1f} bp")
    print("   -> the gap grows with the LEVEL of rates too, at a fixed 182 days:")
    print(f"      {'discount':>10}{'BEY':>11}{'gap (bp)':>11}")
    for d in (0.01, 0.03, 0.05, 0.08, 0.12):
        p = bill_price_from_discount(d, 182)
        b = bond_equivalent_yield(p, 182)
        print(f"      {d:>10.2%}{b:>11.4%}{1e4 * (b - d):>+11.1f}")

    print("\n2. THE TWO FORMULAS ARE IN THE REGULATION, WITH WORKED EXAMPLES")
    print("   31 CFR 356 Appendix B, VI.B.1 (not more than one half-year):")
    ex1 = treasury_investment_rate(99.559444, 20, 365)
    print(f"     cash management bill 1990-06-01 -> 1990-06-21, P = 99.559444, r = 20, y = 365")
    print(f"     regulation prints i = 8.076%   this file: {ex1:.6%}  -> {ex1 * 100:.3f}%")
    print("   31 CFR 356 Appendix B, VI.B.2 (more than one half-year, the quadratic):")
    ex2 = treasury_investment_rate(92.265000, 364, 365)
    print(f"     52-week bill 1990-06-07 -> 1991-06-06, P = 92.265000, r = 364, y = 365")
    print(f"     regulation prints i = 8.237%   this file: {ex2:.6%}  -> {ex2 * 100:.3f}%")
    naive = bond_equivalent_yield(92.265000, 364, 365)
    print(f"     the short formula on the same bill would give {naive:.6%} "
          f"({1e4 * (naive - ex2):+.1f} bp too high)")

    print("\n3. CURRENT YIELD IGNORES THE PULL TO PAR")
    print(f"   {'coupon':>8}{'clean':>9}{'years':>7}{'current yield':>15}{'YTM':>11}"
          f"{'gap (bp)':>11}")
    for cpn, clean, yrs in ((0.03, 85.0, 5), (0.03, 85.0, 20), (0.08, 118.0, 5),
                            (0.08, 118.0, 20), (0.05, 100.0, 10)):
        cy = current_yield(cpn, clean)
        y = ytm(clean, cpn, 2 * yrs)
        print(f"   {cpn:>8.2%}{clean:>9.2f}{yrs:>7}{cy:>15.4%}{y:>11.4%}"
              f"{1e4 * (y - cy):>+11.1f}")
    print("   -> current yield is right only at par; on a discount bond it understates and on "
          "a premium bond it overstates")

    print("\n4. YIELD TO WORST ON A CALLABLE TRADING ABOVE PAR")
    CLEAN, CPN = 108.0, 0.05
    ytw = yield_to_worst(CLEAN, CPN, [(4, 102.0), (6, 101.0), (10, 100.0)], 20)
    print(f"   5% bond, 10 years to maturity, clean {CLEAN:.2f}, calls at 102 (2y), 101 (3y), "
          f"100 (5y)")
    for c in ytw["candidates"]:
        tag = "MATURITY" if c["redemption"] == 100.0 and c["periods"] == 20 else "call"
        print(f"     redeem {c['redemption']:6.2f} in {c['periods'] / 2:4.1f}y ({tag:8s})  "
              f"yield {c['yield']:.4%}")
    print(f"   -> yield to maturity {ytw['yield_to_maturity']:.4%}, yield to WORST "
          f"{ytw['yield_to_worst']:.4%} at {ytw['worst_at'] / 2:.1f} years")
    print(f"   -> quoting the YTM overstates by {ytw['bp_ytm_over_ytw']:.1f} bp on a bond the "
          f"issuer will almost certainly call")

    print("\n5. CROSS-CHECK AGAINST QUANTLIB")
    live = quantlib_cross_checks(DISCOUNT, DAYS, 0.05, 0.045, 10)
    if live is None:
        print("   QuantLib not installed - the reference implementation above stands alone")
    else:
        print(f"   QuantLib {live['version']}")
        for b in live["bills"]:
            print(f"   {b['days']:>4}d bill: BEY {b['bey']:.6%}; InterestRate(Simple, ACT/365)"
                  f".compoundFactor = {b['ql_compound_factor']:.10f} vs 100/P = "
                  f"{b['direct']:.10f}  |diff| {abs(b['ql_compound_factor'] - b['direct']):.1e}")
        mine = bond_price_from_yield(0.05, 0.045, live["periods"])["clean"]
        print(f"   10y 5% semiannual at y = 4.50%: QuantLib clean {live['bond_clean']:.10f}  "
              f"mine {mine:.10f}  |diff| {abs(live['bond_clean'] - mine):.1e}")
        mine_y = ytm(live["bond_clean"], 0.05, live["periods"])
        print(f"   and back: QuantLib yield {live['bond_yield']:.10f}  mine {mine_y:.10f}  "
              f"|diff| {abs(live['bond_yield'] - mine_y):.1e}")
        gap = live["bond_clean_following"] - live["bond_clean"]
        print(f"   (the same bond with QuantLib's DEFAULT paymentConvention=Following prices "
              f"{live['bond_clean_following']:.10f}, {gap:+.6f} -- weekend-bumped coupons, not "
              f"a different yield)")

    print("\n" + "=" * W)
    print("RULE: a bill DISCOUNT RATE is not a yield -- it divides by face on a 360-day year.")
    print("      Convert with 31 CFR 356 App. B: simple up to one half-year, the QUADRATIC")
    print("      beyond it. Current yield ignores the pull to par; on a callable, quote YTW.")
    print("=" * W)
